(() => {
  'use strict';
  const data=window.GAME_UI_DATA, api=window.GameUI, ui=api.ui;
  const groups=data.screenGroups, screens=groups.flatMap(g=>g.screens.map(s=>({...s,groupId:g.id,groupName:g.name}))), byId=new Map(screens.map(s=>[s.id,s]));
  const defaults={silver:2460,hull:72,sails:88,crew:38,maxCrew:60,morale:78,ammo:'solid',stock:{grain:80,wood:24,iron:16,silk:12,porcelain:8,spices:6},selectedGood:'silk',selectedCrew:'awang',selectedItem:'compass',equipped:'短刀',refit:'基础索具',post:'领航',contractAccepted:false,questAccepted:false,letterSent:false,sentLetters:0,share:35,paused:false,weather:'晴',speed:8.6,zoom:1,formation:'并列',leftShots:12,rightShots:12,reloading:false,saves:[],settings:{music:60,effects:75,text:100,reducedMotion:false,colorAssist:false},transactions:[{title:'上一航次货物结清',delta:620,balance:2460,category:'贸易',time:'昨日'},{title:'船员酬银',delta:-90,balance:1840,category:'船员',time:'前日'}],notice:''};
  Object.assign(defaults,{careerMode:'故事体验',sentLetterRecords:[],acceptedContracts:[],contractDeliveries:{},recruitRecords:[],cargoCapacity:350,cargoOwnership:{},marketStock:{silk:32,porcelain:18,spices:9,grain:96,wood:42,iron:26},notifications:[],notificationCounter:0});
  Object.assign(defaults.settings,{voice:70,quality:'均衡',windowMode:'无边框窗口',highContrast:false,navigationAssist:true,holdToToggle:false,subtitles:true});
  let state=structuredClone(defaults),current='main-menu',filter='all',selectedFlow=data.flows[0]?.id,toastTimer;
  const main=document.getElementById('main-content'),dialog=document.getElementById('directory-dialog');
  const params=new URLSearchParams(location.search);document.body.classList.toggle('embed',params.has('embed'));document.body.classList.toggle('capture',params.has('capture'));
  document.getElementById('page-count').textContent=screens.length;
  const go=id=>{if(location.hash.slice(1)===id)render();else location.hash=id;};
  const notify=message=>{state.notice=message;const error=/不足|无效|请先|最多|已满|无法|不可|未保存|还没有/.test(message);state.feedback={message,error};state.notifications.unshift({id:`notice-${++state.notificationCounter}`,title:error?'这项安排尚未完成':'船上新记',body:message,category:error?'提醒':'事务',time:'刚刚',pageId:byId.has(current)?current:'notification-log',read:false});state.notifications=state.notifications.slice(0,60);const feedback=document.getElementById('action-feedback');if(feedback){feedback.hidden=false;feedback.classList.toggle('is-error',error);feedback.querySelector('span').textContent=message;}const node=document.getElementById('toast');node.textContent=message;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),4200);};
  function transact(delta,title,category='交易') {state.silver+=delta;state.transactions.unshift({title,delta,balance:state.silver,category,time:'刚刚'});}
  const afford=(cost)=>{if(!Number.isFinite(cost)||cost<0){notify('金额无效，请重新选择。');return false;}if(state.silver<cost){notify(`银两不足，尚差 ${cost-state.silver} 两。`);return false;}return true;};
  function refreshLetterForm(){
    const body=document.getElementById('letter-body'),amountInput=document.getElementById('remittance');if(!body||!amountInput)return;
    const button=main.querySelector('[data-action="send-letter"]');if(!button)return;
    const text=body.value.trim(),amount=Number(amountInput.value),carrier=state.letterCarrier||'trusted';
    const recipient=document.getElementById('letter-recipient')?.value||'平户家人',sameDraft=state.lastLetter&&state.lastLetter.body===text&&state.lastLetter.amount===amount&&state.lastLetter.recipient===recipient;
    const reason=!text?'请先写下要寄给家中的话。':text.length>800?'家书请控制在800字以内。':!Number.isInteger(amount)||amount<0?'家用须为非负整数。':sameDraft?'这封信已经托寄，修改正文或家用后再寄新信。':amount+20>state.silver?`银两不足，尚差 ${amount+20-state.silver} 两。`:carrier!=='trusted'?'先找到可信的托话人，再将信交出。':state.previewScenario==='银两待筹'?'这笔家用尚未筹齐，请先安排银两。':'';
    button.disabled=!!reason;button.setAttribute('aria-disabled',String(!!reason));
    const note=document.getElementById('letter-submit-reason');if(note)note.textContent=reason;
    const count=document.getElementById('letter-character-count');if(count)count.textContent=`${body.value.length} / 800字`;
  }
  function runAction(button){
    const {action,item,price,key,value,slot,post,side,message}=button.dataset;const cost=Number(price||0);let rerender=true;
    switch(action){
      case 'set':state[key]=value;if(key==='selectedAct'){state.selectedScene=null;state.dialogueLine=0;}if(key==='route'||key==='destination'){state.routeConfirmed=null;state.routeConfirmedDestination=null;}break;
      case 'toggle':state[key]=!state[key];break;
      case 'settings-reset':state.settings=structuredClone(defaults.settings);notify('偏好设置已恢复默认值。');break;
      case 'open':state[key]=value;if(key==='selectedScene')state.dialogueLine=0;if(key==='route'||key==='destination'){state.routeConfirmed=null;state.routeConfirmedDestination=null;}go(button.dataset.target);return;
      case 'buy':case 'sell':{
        const input=document.getElementById('trade-quantity');const qty=input?Number(input.value):1;
        if(!Number.isInteger(qty)||qty<1||qty>999){notify('数量须为1至999之间的整数。');return;}
        if(input?.max && qty>Number(input.max)){notify(`本次最多可交易 ${input.max} 单位，请减少数量。`);return;}
        if(action==='buy'){
          if(item!=='merchant-ship'){
            if(button.dataset.market==='port'&&qty>Number(state.marketStock[item]||0)){notify('本港现货不足，请重新核对数量。');return;}
            if(ui.cargoUsed(state)+qty*(ui.cargoWeights[item]||1)>state.cargoCapacity){notify('剩余货舱不足，请减少数量或先出售存货。');return;}
          }
          if(!afford(cost*qty))return;
          if(item==='merchant-ship'){if(state.shipOrdered){notify('船坞已经在建造这条船。');return;}state.shipOrdered=true;state.orderedShipType=button.dataset.model||'merchant';state.orderedShipName=button.dataset.name||'海贸福船';transact(-cost,`船坞订造${state.orderedShipName}`,'舰船');notify(`已付${state.orderedShipName}订造款，船坞开始备料。`);}
          else {transact(-cost*qty,`购入${{silk:'生丝',grain:'粮食',wood:'木料',iron:'铁料',porcelain:'瓷器',spices:'香料'}[item]||item} × ${qty}`);state.stock[item]=(state.stock[item]||0)+qty;if(button.dataset.market==='port')state.marketStock[item]-=qty;notify(`已购入 ${qty} 批货物，支付 ${cost*qty} 两。`);}
        }else{if((state.stock[item]||0)<qty){notify('舱中存货不足，请减少卖出数量。');return;}state.stock[item]-=qty;if(button.dataset.market==='port')state.marketStock[item]=(state.marketStock[item]||0)+qty;transact(cost*qty,`出售货物 × ${qty}`);notify(`已售出 ${qty} 批货物，收入 ${cost*qty} 两。`);}
        break;
      }
      case 'repair':if(state.hull>=100){notify('船体已修复，无需重复花费。');return;}if(!afford(380))return;transact(-380,'修补船体','舰船');state.hull=100;notify('船体修复完成，耐久恢复至100%。');break;
      case 'refit':if(state.refit===item){notify('此部件已装设。');return;}if(!afford(cost))return;transact(-cost,`装设${item}`,'舰船');state.refit=item;notify(`已装设：${item}。`);break;
      case 'recruit':if(state.crew>=state.maxCrew){notify('船上铺位已满。');return;}if(!afford(cost))return;transact(-cost,`招募${item||'水手'}`,'船员');state.crew++;state.recruited=item;state.recruitRecords.push({id:`recruit-${state.recruitRecords.length+1}`,item:item||'水手',role:item||'水手',price:cost});notify('一名新船员加入，船上铺位已更新。');break;
      case 'assign':{const person=item||state.selectedCrew,target=post||state.post;state.assignment=Object.fromEntries(Object.entries(state.assignment||{}).filter(([assignedPost,id])=>id!==person&&assignedPost!==target));state.assignment[target]=person;state.post=target;notify(`岗位已安排：${state.post}。`);break;}
      case 'ammo':state.ammo=item;notify(`装填选择：${{solid:'实心弹',chain:'链弹',grape:'葡萄弹'}[item]||item}。`);break;
      case 'fire':{
        if(state.reloading){notify('炮手仍在装填，请稍候。');return;}const shotKey=side==='right'?'rightShots':'leftShots';if(state[shotKey]<=0){notify('本舷弹药不足，请重新补给。');return;}
        state[shotKey]--;state.reloading=true;notify('已发出开炮指令，炮手开始重新装填。');setTimeout(()=>{state.reloading=false;if(current==='battle-hud'||current==='ammo-loading')render();notify('本舷重新装填完成。');},1600);break;
      }
      case 'send-letter':{
        const body=document.getElementById('letter-body')?.value.trim();const amount=Number(document.getElementById('remittance')?.value||0);const recipient=document.getElementById('letter-recipient')?.value||'平户家人';
        if(!body){notify('请先写下要寄出的家书。');return;}if(body.length>800){notify('家书请控制在800字以内。');return;}if(!Number.isInteger(amount)||amount<0){notify('汇银须为非负整数。');return;}if(state.lastLetter&&state.lastLetter.body===body&&state.lastLetter.amount===amount&&state.lastLetter.recipient===recipient){notify('这封信已经托寄，修改正文或家用后再寄新信。');return;}if((state.letterCarrier||'trusted')!=='trusted'){notify('请先找到可信托话人，再交出家书。');return;}if(!afford(amount+20))return;
        transact(-amount-20,`捎信至${recipient}，附银${amount}两`,'家书');state.letterSent=true;state.sentLetters++;
        state.lastLetter={id:`sent-${state.sentLetters}`,title:`寄往${recipient}的家书`,recipient,body,amount,date:'已托寄 · 等待回音'};
        state.sentLetterRecords=[state.lastLetter,...(state.sentLetterRecords||[])];state.letterDraft=body;state.remittanceDraft=amount;state.letterRecipient=recipient;state.selectedLetter=state.lastLetter.id;state.letterFilter='sent';
        notify(`家书已交托，附银 ${amount} 两，捎信费 20 两。`);break;
      }
      case 'accept-contract':if(state.acceptedContracts.includes(item)){notify('这份委托已经承接，请到日志查看。');return;}state.contractAccepted=true;state.selectedContract=item;state.acceptedContract=item;state.acceptedContracts.push(item);notify('已接下契约，任务与账册可查看相关约定。');break;
      case 'deliver-contract':if(!state.acceptedContracts.includes(item)){notify('请先承接这份委托，再提交履约记录。');return;}if(state.contractDeliveries[item]){notify('这份履约记录已经提交，仍待对方核验。');return;}state.contractDeliveries[item]='pending';notify('履约记录已交出，报酬仍待对方核验后结清。');break;
      case 'mark-notification':{const entry=state.notifications.find(x=>x.id===button.dataset.id);if(entry)entry.read=true;break;}
      case 'route-confirm':{const needed=state.route==='直航'?110:80;if((state.stock.grain||0)<needed){notify(`出航粮食不足，建议至少准备 ${needed} 单位。`);return;}state.routeConfirmed=state.route||'沿岸';state.routeConfirmedDestination=state.destination||'平户';state.routeConfirmedAt='本次出港';notify(`已确认${state.routeConfirmed==='直航'?'顺风直航':'沿岸稳行'}航路，领航人已收到安排。`);go('sailing-hud');return;}
      case 'accept-quest':state.questAccepted=true;state.activeQuest=item;notify('已将此事记入航海日志。');break;
      case 'save':{const index=Number(slot||0);const draftInput=document.getElementById('save-name');if(draftInput)state.saveNameDraft=draftInput.value;if(state.saves[index]&&state.confirmSaveSlot!==index){state.confirmSaveSlot=index;notify('此档已有记录，请再次核对后确认覆盖。');break;}const name=document.getElementById('save-name')?.value.trim()||'厦门外海·出港前';state.confirmSaveSlot=null;const snapshot=structuredClone({...state,saves:[],feedback:null});state.saves[index]={name,hull:state.hull,silver:state.silver,snapshot};notify('本次演示存档已保存，可在载入页查看。');break;}
      case 'load':{const saved=state.saves[Number(slot||0)];if(!saved?.snapshot){notify('此档还没有保存过航程，请选择已有记录。');return;}const slots=state.saves;state=structuredClone(saved.snapshot);state.saves=slots;notify('已载入航行状态。');go('sailing-hud');return;}
      case 'choose':{
        if(item==='crew-feast'||item==='crew-pay'){if(item==='crew-pay'&&state.wagesPaid){notify('本期船员酬银已经结清。');return;}if(!afford(cost))return;transact(-cost,item==='crew-feast'?'船上加餐':'补发船员酬银','船员');if(item==='crew-pay')state.wagesPaid=true;state.morale=Math.min(100,state.morale+(item==='crew-feast'?6:12));notify('船员士气已更新。');}
        else if(item?.startsWith('battle-order-')){state.confirmedBattleOrder=item;notify('令旗已升起，僚船正在照令调整船位。');}
        else if(item?.startsWith('jettison-')){const good=item.slice(9),quantity=Number(button.dataset.quantity);if(!Object.hasOwn(state.stock,good)||!Number.isInteger(quantity)||quantity<1||quantity>state.stock[good]){notify('抛货数量无效，请核对自有库存。');return;}if(state.cargoOwnership?.[good]==='disputed'){notify('这批货的归属尚待核实，不可擅自抛弃。');return;}state.stock[good]-=quantity;state.jettisonReceipt={item:good,quantity};notify(`已抛下 ${quantity} 单位货物，货舱载荷已减少。`);}
        else if(item==='damage-patch'){if(!afford(cost))return;transact(-cost,'战中临时补漏','战斗');state.hull=Math.min(100,state.hull+8);notify('补漏已完成，船体耐久提高。');}
        else if(item==='damage-fire'){state.fireContained=true;notify('损管队已压制火势。');}
        else if(item?.startsWith('boarding-')){state.boardingStage=item==='boarding-advance'?'推进到主甲板':item==='boarding-hold'?'守住过板':'已脱离接舷';notify(`接舷命令：${state.boardingStage}。`);}
        else if(item==='battle-result-claim'){if(state.battleClaimed){notify('本场战报已结算。');return;}state.battleClaimed=true;transact(460,'战后货物估价收入','战斗');notify('战报已结清，收入460两。');}
        else if(item==='prize-claim'){if(state.prizeClaimed){notify('本次战利品已经分配。');return;}state.prizeClaimed=true;const income=Math.round(800*(100-Number(state.share))/100);transact(income,'战利品分利后的船主份额','分利');state.morale=Math.min(100,state.morale+5);notify(`分利已记账，船主所得 ${income} 两，船员份额 ${state.share}%。`);}
        else notify(message||'已确认这项安排，相关选择保留在本次演示中。');state.choice=item;break;
      }
      case 'notice':notify(message||'已记下这项安排。');rerender=false;break;
      case 'reset':state=structuredClone(defaults);notify('演示状态已恢复。');break;
      default:notify('请选择一个可用行动。');rerender=false;
    }
    if(rerender)render();
  }
  function nav(screen){const tabs=[['sailing-hud','compass','航行'],['sea-chart','map','海图'],['ship-overview','ship','舰船'],['inventory','bag','行囊'],['crew-roster','people','船员'],['quest-journal','book','日志'],['letters','letter','家书'],['port-hub','anchor','港口']];const families={'sailing-hud':['sailing-hud','weather-wind','sea-encounter'],'sea-chart':['sea-chart','destination-detail','route-plan'],'ship-overview':['ship-overview','fleet','ship-refit','ship-repair','cargo-hold','shipyard'],'inventory':['inventory','item-detail','equipment','character-profile','character-growth'],'crew-roster':['crew-roster','crew-detail','crew-recruit','crew-assign','crew-morale'],'quest-journal':['quest-journal','quest-detail','chronicle','intelligence','relationships'],'letters':['letters','letter-detail','send-letter-remittance','home','family','child-growth'],'port-hub':['port-hub','market','trade-order','contract-board','contract-detail','black-market','supplies']};return `<nav class="game-nav" aria-label="游戏功能">${tabs.map(([id,icon,title])=>ui.go(id,`${ui.icon(icon)}<span>${title}</span>`,` ${(families[id]||[id]).includes(screen.id)?'active':''}`)).join('')}</nav>`;}
  function renderScreen(screen){
    const immersive=['main-menu','sailing-hud','battle-hud','dialogue','scene-briefing','ending','boarding'].includes(screen.id);
    const renderer=api.renderers.get(screen.id);let html;
    try{html=renderer?renderer(screen,state,ui):`<div class="empty-state"><h1>${ui.e(screen.title)}</h1><p>此页面尚未完成渲染集成。</p></div>`;}catch(error){console.error('UI_RENDER_ERROR',screen.id,error);html=`<section class="empty-state"><h1>页面载入异常</h1><p>${ui.e(screen.title)}</p></section>`;}
    const scenario=state.previewScenario||'';
    return `<div class="screen-review"><span>${ui.e(screen.groupName)} / ${ui.e(screen.title)} · ${screens.indexOf(screen)+1} / ${screens.length}</span><div><label>页面状态<select id="preview-state"><option value="">正常</option>${screen.states.map(s=>`<option value="${ui.e(s)}" ${scenario===s?'selected':''}>${ui.e(s)}</option>`).join('')}</select></label></div><div class="toolbar"><button class="text-link" data-action="open" data-key="statePage" data-value="${ui.e(screen.id)}" data-target="states">查看全部状态图片</button><button class="text-link" data-action="reset">重置演示</button></div></div><section class="game-window ${immersive?'immersive':''}" data-page="${ui.e(screen.id)}"><header class="game-topbar"><span class="game-brand">海上明旗</span><div class="resource-strip"><span>${ui.icon('coin')} 银两<strong data-silver>${state.silver.toLocaleString()}</strong></span><span>船员<strong>${state.crew} / ${state.maxCrew}</strong></span><span>士气<strong>${state.morale}</strong></span><button class="icon-button" data-go="pause-menu" aria-label="暂停与设置">${ui.icon('settings')}</button></div></header><div class="game-content">${scenario?`<aside class="state-banner"><strong>${ui.e(scenario)}</strong><p>${ui.e(screen.description)} · 此状态用于审阅信息提示、禁用条件与恢复入口。</p>${ui.action('set','恢复正常界面','button quiet',{key:'previewScenario',value:''})}</aside>`:''}${html}</div>${screen.id==='main-menu'?'':nav(screen)}</section>`;
  }
  function renderOverview(){const chosen=filter==='all'?screens:screens.filter(s=>s.groupId===filter);return `<section class="review-page"><header><div><p class="context-label">全页面审阅</p><h1>一段生涯，${screens.length} 个界面</h1><p>航行、交锋、贸易与归家。每一页都可打开操作，状态只保留在本次演示中。</p></div><div class="toolbar">${ui.go('main-menu','进入游戏首页','button primary')}<a class="button" href="../systems.md">完整系统文档</a></div></header><div class="catalog-filters"><button data-filter="all" class="${filter==='all'?'active':''}">全部 ${screens.length}</button>${groups.map(g=>`<button data-filter="${ui.e(g.id)}" class="${filter===g.id?'active':''}">${ui.e(g.name)} ${g.screens.length}</button>`).join('')}</div><div class="preview-grid">${chosen.map(s=>`<a class="preview-card" href="#${s.id}" data-preview-link="${s.id}">${data.previewIds.includes(s.id)?`<img loading="lazy" src="previews/${s.id}.jpg" alt="${ui.e(s.title)}界面完整预览" width="1440" height="1000">`:`<div class="preview-live"><iframe loading="lazy" tabindex="-1" title="${ui.e(s.title)}实时预览" src="?embed=1#${s.id}"></iframe></div>`}<div><h2>${ui.e(s.title)}</h2><p>${ui.e(s.groupName)} · ${ui.e(s.description)}</p></div></a>`).join('')}</div></section>`;}
  function renderSystems(){const found=data.underlyingSystems||[];return `<section class="review-page"><header><div><p class="context-label">从剧情到玩法</p><h1>${data.systems.length} 个玩法系统 · ${found.length} 个底层系统</h1><p>优先级表示日后正式开发顺序。本轮所有页面均提供UI；现有实现与设计目标分别记录在系统文档。</p></div><a class="button" href="../systems.md">阅读完整清单</a></header><table class="system-table"><thead><tr><th>系统</th><th>作用与剧情依据</th><th>优先级</th><th>对应界面</th></tr></thead><tbody>${data.systems.map(s=>`<tr><td>${ui.e(s.name)}</td><td>${ui.e(s.purpose)}<div class="small muted">${s.storyRefs.slice(0,3).map(id=>ui.e(data.scenes.find(x=>x.id===id)?.title||id)).join(' / ')}</div></td><td>${ui.pill(s.priority)}</td><td><div class="page-links">${s.pages.map(id=>`<a href="#${id}">${ui.e(byId.get(id)?.title||id)}</a>`).join('')}</div></td></tr>`).join('')}</tbody></table><h2 style="margin-top:45px">支撑海上世界的底层能力</h2><div class="foundation-list">${found.map(s=>`<article><h3>${ui.e(s.name)}</h3><p>${ui.e(s.purpose)}</p><p>${ui.e(s.existingImplementation?.summary||'')}</p><div class="tag-list">${(s.mappedPages||[]).map(id=>ui.go(id,ui.e(byId.get(id)?.title||id),'button quiet')).join('')}</div></article>`).join('')}</div></section>`;}
  function renderFlows(){const flow=data.flows.find(f=>f.id===selectedFlow)||data.flows[0];return `<section class="review-page"><header><div><p class="context-label">玩法与界面连贯性</p><h1>让一次行动走得完整</h1><p>从接到消息，到做出安排，再到资源与关系的后果。选择一条流程即可逐页体验。</p></div></header><div class="flow-layout"><nav class="flow-menu">${data.flows.map(f=>`<button class="button ${flow.id===f.id?'selected':''}" data-flow="${f.id}">${ui.e(f.title)}</button>`).join('')}</nav><div><h2>${ui.e(flow.title)}</h2><div class="flow-chain">${flow.screenIds.map((id,i)=>`<a class="flow-node" href="#${id}"><small>步骤 ${i+1}</small><strong>${ui.e(byId.get(id)?.title||id)}</strong></a>`).join('')}</div><div class="flow-details"><p>${ui.e(flow.description||flow.title)}</p><div class="tag-list">${flow.storyRefs.map(id=>ui.pill(data.scenes.find(s=>s.id===id)?.title||id)).join('')}</div>${ui.go(flow.screenIds[0],'从第一步开始','button primary')}</div></div></div></section>`;}
  function renderStates(){const page=byId.get(state.statePage)||screens[0],shots=data.statePreviews?.[page.id]||[],total=Object.values(data.statePreviews||{}).reduce((n,x)=>n+x.length,0);return `<section class="review-page"><header><div><p class="context-label">默认之外，细节还在状态之中</p><h1>逐页状态画册</h1><p>空白、受损、缺少资源、正在处理与完成之后。以下均为同一可操作界面的真实截图，共 ${total} 张。</p></div>${ui.go(page.id,'操作这一页','button primary')}</header><label class="state-page-select">选择页面<select id="state-page-choice">${groups.map(g=>`<optgroup label="${ui.e(g.name)}">${g.screens.map(s=>`<option value="${s.id}" ${s.id===page.id?'selected':''}>${ui.e(s.title)}</option>`).join('')}</optgroup>`).join('')}</select></label><div class="state-preview-grid"><article><a href="previews/${page.id}.jpg"><img src="previews/${page.id}.jpg" alt="${ui.e(page.title)}正常状态"></a><h2>正常状态</h2></article>${shots.map(s=>`<article><a href="previews/states/${s.file}"><img loading="lazy" src="previews/states/${s.file}" alt="${ui.e(page.title+' · '+s.state)}"></a><h2>${ui.e(s.state)}</h2><a class="button quiet" href="?state=${encodeURIComponent(s.state)}#${page.id}">打开这个演示状态</a></article>`).join('')}</div></section>`;}
  function render(){
    const focusKey=document.activeElement?.getAttribute?.('data-focus-key');
    const id=decodeURIComponent(location.hash.slice(1)||'main-menu');current=id;
    document.body.classList.toggle('large-text',state.settings.text>110);document.body.classList.toggle('color-assist',state.settings.colorAssist);
    document.body.classList.toggle('high-contrast',!!state.settings.highContrast);
    if(id==='overview')main.innerHTML=renderOverview();
    else if(id==='systems')main.innerHTML=renderSystems();
    else if(id==='flows')main.innerHTML=renderFlows();
    else if(id==='assets')main.innerHTML=window.renderProductionAssets(data,state,ui);
    else if(id==='states')main.innerHTML=renderStates();
    else if(byId.has(id))main.innerHTML=renderScreen(byId.get(id));
    else main.innerHTML=`<section class="review-page"><h1>未找到这个页面</h1>${ui.go('main-menu','返回首页','button primary')}</section>`;
    document.querySelectorAll('select[data-setting]').forEach(input=>{const value=state.settings[input.dataset.setting];if(value!==undefined)input.value=value;});
    document.body.classList.toggle('reduced-motion',!!state.settings.reducedMotion);
    main.querySelectorAll('button.selected,button.tab.active,button.decision-option').forEach(button=>button.setAttribute('aria-pressed',String(button.classList.contains('selected')||button.classList.contains('active'))));
    main.querySelectorAll('.game-nav button.active').forEach(button=>button.setAttribute('aria-current','page'));
    if(byId.has(id)&&!main.querySelector('.immersive')){const feedback=document.createElement('div');feedback.id='action-feedback';feedback.className=`action-feedback ${state.feedback?.error?'is-error':''}`;feedback.hidden=!state.feedback;feedback.setAttribute('role','note');feedback.setAttribute('aria-label','行动结果');feedback.innerHTML=`${ui.icon(state.feedback?.error?'flag':'check')}<span>${ui.e(state.feedback?.message||'')}</span>${ui.go('notification-log','查看消息','button quiet')}`;main.querySelector('.game-content')?.prepend(feedback);}
    if(params.has('capture'))document.querySelectorAll('img').forEach(image=>{image.loading='eager';});
    const focusCounts=new Map();main.querySelectorAll('button[data-action],button[data-go]').forEach(button=>{const d=button.dataset,base=[d.action||d.go,d.key||d.item||'',d.side||d.slot||d.post||'',d.target||''].join(':'),ordinal=focusCounts.get(base)||0;focusCounts.set(base,ordinal+1);button.setAttribute('data-focus-key',`${base}:${ordinal}`);});
    if(focusKey)[...main.querySelectorAll('[data-focus-key]')].find(button=>button.getAttribute('data-focus-key')===focusKey)?.focus?.({preventScroll:true});
    document.title=`${byId.get(id)?.title||({overview:'全部页面',systems:'系统总表',flows:'玩法流程',assets:'模型与美术',states:'逐页状态画册'}[id]||'界面原型')} · 海上明旗`;
  }
  function directory(query=''){const term=query.trim();document.getElementById('directory-results').innerHTML=groups.map(g=>{const list=g.screens.filter(s=>!term||`${s.title} ${s.description} ${g.name}`.includes(term));return list.length?`<section class="directory-group"><h3>${ui.e(g.name)}</h3>${list.map(s=>`<a data-screen-link="${s.id}" href="#${s.id}">${ui.e(s.title)}</a>`).join('')}</section>`:'';}).join('')||'<p class="muted">没有匹配页面，请尝试较短的词。</p>';}
  document.getElementById('screen-directory').addEventListener('click',()=>{directory();dialog.showModal();document.getElementById('page-search').focus();});
  document.getElementById('directory-close').addEventListener('click',()=>dialog.close());document.getElementById('page-search').addEventListener('input',event=>directory(event.target.value));
  document.addEventListener('click',event=>{const button=event.target.closest('[data-go],[data-action],[data-view],[data-filter],[data-flow]');if(button){if(button.disabled)return;if(button.dataset.go)go(button.dataset.go);else if(button.dataset.action)runAction(button);else if(button.dataset.view)go(button.dataset.view);else if(button.dataset.filter){filter=button.dataset.filter;render();}else if(button.dataset.flow){selectedFlow=button.dataset.flow;render();}}const anchor=event.target.closest('a[href^="#"]');if(anchor&&dialog.open)dialog.close();});
  document.addEventListener('change',event=>{if(event.target.id==='state-page-choice'){state.statePage=event.target.value;render();}if(event.target.id==='letter-recipient'){state.letterRecipient=event.target.value;refreshLetterForm();}if(event.target.id==='preview-state'){state.previewScenario=event.target.value;render();}if(event.target.dataset.setting){const input=event.target;state.settings[input.dataset.setting]=input.type==='checkbox'?input.checked:input.type==='range'?Number(input.value):input.value;render();}});
  document.addEventListener('input',event=>{if(event.target.id==='save-name')state.saveNameDraft=event.target.value;if(event.target.id==='letter-body'){state.letterDraft=event.target.value;refreshLetterForm();}if(event.target.id==='remittance'){state.remittanceDraft=event.target.value;refreshLetterForm();const amount=Number(event.target.value),total=document.getElementById('letter-total'),balance=document.getElementById('letter-balance');if(total)total.textContent=Number.isFinite(amount)?String(amount+20):'—';if(balance)balance.textContent=Number.isFinite(amount)?(state.silver-amount-20).toLocaleString():'—';}if(event.target.type==='range'){const output=event.target.closest('label')?.querySelector('output');if(output)output.textContent=event.target.value;}if(event.target.id==='trade-quantity'){const input=event.target,total=Number(input.value)*Number(input.dataset.unitPrice),buy=input.dataset.tradeMode!=='sell';const priceNode=document.getElementById('trade-total'),balanceNode=document.getElementById('trade-balance');if(priceNode)priceNode.textContent=Number.isFinite(total)?total.toLocaleString():'—';if(balanceNode)balanceNode.textContent=Number.isFinite(total)?(state.silver+(buy?-total:total)).toLocaleString():'—';const cargoAfter=document.getElementById('trade-cargo-after');if(cargoAfter)cargoAfter.textContent=String(Number(input.dataset.cargoUsed||ui.cargoUsed(state))+(buy?1:-1)*Number(input.value||0)*Number(input.dataset.unitWeight||1));}});
  document.addEventListener('keydown',event=>{
    if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||dialog.open||event.ctrlKey||event.metaKey||event.altKey)return;
    if((event.key==='Enter'||event.key===' ')&&event.target.matches('[role="button"][data-action]')){event.preventDefault();runAction(event.target);return;}
    if(event.key==='Enter'&&event.target.matches('[role="button"][data-go]')){event.preventDefault();go(event.target.dataset.go);return;}
    if(!byId.has(current))return;
    if(event.key==='Escape'){event.preventDefault();go(current==='pause-menu'?'sailing-hud':'pause-menu');return;}
    const shortcut={m:'sea-chart',i:'inventory',c:'crew-roster',j:'quest-journal',l:'letters'}[event.key?.toLowerCase()];if(shortcut){event.preventDefault();go(shortcut);return;}
    if(current==='battle-hud'&&['q','e'].includes(event.key?.toLowerCase())){event.preventDefault();const button=main.querySelector(`[data-action="fire"][data-side="${event.key.toLowerCase()==='q'?'left':'right'}"]`);if(button&&!button.disabled)runAction(button);}
  });
  window.addEventListener('hashchange',()=>{state.previewScenario='';state.feedback=null;render();window.scrollTo(0,0);});
  const requestedState=params.get('state'),initialPage=byId.get(decodeURIComponent(location.hash.slice(1)));if(initialPage?.states.includes(requestedState))state.previewScenario=requestedState;
  api.pages=screens;api.getState=()=>structuredClone(state);api.navigate=go;render();
  console.info('GAME_UI_READY',JSON.stringify({pages:screens.length,registered:api.renderers.size,missing:screens.filter(s=>!api.renderers.has(s.id)).map(s=>s.id)}));
})();
